SourceCode.Declaration:
/// <summary>
/// This class is an extension of the SalesTable form data source to manage the custom label field based on customer settings.
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTable, SalesTable))]
final class AVARUMSalesTable_SalesTableDS_Extension
{
}

Method.Source:
/// <summary>
/// This method is called when the form data source is activated.
/// </summary>
/// <returns></returns>
int active()
{
    int result;
    FormDataSource salesTableDS;
    FormDataSource salesLineDS;
    CustTable custTable;
    SalesTable salesTable;
    FormDataObject salesLineCustomLabelObj;

    result = next active();

    salesTableDS = this as FormDataSource;
    salesLineDS = this.formRun().dataSource(formDataSourceStr(SalesTable, SalesLine));
    salesTable = salesTableDS.cursor();
    custTable = salesTable.custTable_CustAccount();
    salesLineCustomLabelObj = salesLineDS.object(fieldNum(SalesLine, AVARUMSalesCustomerLabel));

    salesLineCustomLabelObj.enabled(custTable.AVARUMSalesCustomerLabelMandatory);
    salesLineCustomLabelObj.mandatory(custTable.AVARUMSalesCustomerLabelMandatory);

    return result;
}
